"""Deterministic synthetic assets, never generated by SF3D or a physical scan.

The image labels and node names identify source FRONT(+X), UP(+Z), LEFT(+Y).
Two material primitives share one embedded PNG; scene fixtures instance the mesh.
"""
import io
import json
import struct

import numpy as np
from PIL import Image, ImageDraw
import trimesh


def encode(doc, binary):
    doc["buffers"] = [{"byteLength": len(binary)}]
    js = json.dumps(doc, sort_keys=True, separators=(",", ":")).encode()
    js += b" " * (-len(js) % 4)
    binary = bytes(binary) + b"\0" * (-len(binary) % 4)
    return (struct.pack("<4sII", b"glTF", 2, 28 + len(js) + len(binary))
            + struct.pack("<I4s", len(js), b"JSON") + js
            + struct.pack("<I4s", len(binary), b"BIN\0") + binary)


def fixture(kind="complex"):
    doc = {"asset": {"version": "2.0", "generator": "SYNTHETIC B04 FIXTURE"},
           "scene": 0, "scenes": [{"nodes": [0]}], "bufferViews": [], "accessors": [],
           "samplers": [{"magFilter": 9729, "minFilter": 9729, "wrapS": 10497, "wrapT": 10497}],
           "textures": [{"source": 0, "sampler": 0}], "materials": [
               {"name": "synthetic-front-up-left", "pbrMetallicRoughness": {
                   "baseColorTexture": {"index": 0}, "baseColorFactor": [1, 0.8, 0.7, 1],
                   "metallicFactor": 0.2, "roughnessFactor": 0.65}, "doubleSided": False},
               {"name": "synthetic-back", "pbrMetallicRoughness": {
                   "baseColorTexture": {"index": 0}, "metallicFactor": 0.8, "roughnessFactor": 0.3},
                "emissiveFactor": [0.1, 0.2, 0.3]}]}
    binary = bytearray()
    def data_view(raw):
        binary.extend(b"\0" * (-len(binary) % 4))
        index = len(doc["bufferViews"])
        doc["bufferViews"].append({"buffer": 0, "byteOffset": len(binary), "byteLength": len(raw)})
        binary.extend(raw)
        return index
    def array(values, type_):
        values = np.array(values, dtype="<f4")
        doc["accessors"].append({"bufferView": data_view(values.tobytes()), "componentType": 5126,
                                 "count": len(values), "type": type_,
                                 "min": values.min(axis=0).tolist(), "max": values.max(axis=0).tolist()})
        return len(doc["accessors"]) - 1
    image = Image.new("RGB", (96, 64), (220, 190, 100))
    draw = ImageDraw.Draw(image)
    draw.text((3, 2), "SYNTHETIC", fill=(0, 0, 0))
    draw.text((3, 18), "FRONT +X", fill=(180, 0, 0))
    draw.text((3, 33), "UP +Z", fill=(0, 80, 0))
    draw.text((3, 48), "LEFT +Y", fill=(0, 0, 180))
    stream = io.BytesIO()
    image.save(stream, format="PNG", optimize=False)
    doc["images"] = [{"bufferView": data_view(stream.getvalue()), "mimeType": "image/png"}]
    box = trimesh.creation.box(extents=[1.0, 2.0, 3.0])
    vertices = box.vertices.copy()
    vertices[vertices[:, 2] > 0, 0] += 0.3  # Asymmetric sloped body.
    faces = box.faces
    primitives = []
    for i, part in enumerate((faces[:6], faces[6:])):
        triangles = vertices[part]
        normals = np.cross(triangles[:, 1]-triangles[:, 0], triangles[:, 2]-triangles[:, 0])
        normals /= np.linalg.norm(normals, axis=1)[:, None]
        primitives.append({"attributes": {
            "POSITION": array(triangles.reshape((-1, 3)), "VEC3"),
            "NORMAL": array(np.repeat(normals, 3, axis=0), "VEC3"),
            "TEXCOORD_0": array(np.tile([[0, 0], [1, 0], [0.5, 1]], (len(part), 1)), "VEC2")},
            "material": i, "mode": 4})
    doc["meshes"] = [{"primitives": primitives}]
    if kind == "simple":
        doc["nodes"] = [{"mesh": 0, "name": "SYNTHETIC_BODY"}]
    elif kind == "orientation":
        doc["nodes"] = [
            {"name": "SYNTHETIC_ROOT", "translation": [4, 3, -2], "children": [1, 2, 3, 4]},
            {"mesh": 0, "name": "BODY"},
            {"mesh": 0, "name": "FRONT_+X", "translation": [2, 0, 0], "scale": [0.1]*3},
            {"mesh": 0, "name": "UP_+Z", "translation": [0, 0, 3], "scale": [0.1]*3},
            {"mesh": 0, "name": "LEFT_+Y", "translation": [0, 3, 0], "scale": [0.1]*3}]
    else:
        a = np.pi / 6
        doc["nodes"] = [
            {"translation": [4, 3, -2], "rotation": [0, float(np.sin(a/2)), 0, float(np.cos(a/2))], "children": [1, 2]},
            {"mesh": 0, "name": "INSTANCE_A", "scale": [2, 0.5, 1.5], "translation": [1, 2, 0]},
            {"rotation": [0, 0, float(np.sin(-a/2)), float(np.cos(-a/2))], "children": [3]},
            {"mesh": 0, "name": "INSTANCE_B_SHARED", "translation": [-2, 0.7, 1], "scale": [-1, 1.2, 0.8]}]
    return encode(doc, binary)
